import img1 from "../assets/1.jpeg";
import img2 from "../assets/2.jpeg";
import img3 from "../assets/3.jpeg";

const products = [
  {
    id: 1,
    name: "Pink Baby Set",
    price: 899,
    category: "Sweater",
    image: img1,
  },
  {
    id: 2,
    name: "Blue Baby Set",
    price: 899,
    category: "Sweater",
    image: img2,
  },
  {
    id: 3,
    name: "Yellow Baby Set",
    price: 899,
    category: "Sweater",
    image: img3,
  },
];

export default products;
